CREATE TABLE IF NOT EXISTS ai_services (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255),
    provider VARCHAR(255),
    model VARCHAR(255),
    type VARCHAR(50),
    input_price_per_1k_tokens DECIMAL(10, 4),
    output_price_per_1k_tokens DECIMAL(10, 4),
    supports_sql BOOLEAN,
    max_tokens INT,
    context_window VARCHAR(20),
    available BOOLEAN,
    launched_at DATE,
    description TEXT
);

